--liquibase formatted sql

--changeset demp:001-integration-operation
-- The primary key comes from the command (generated by Resolution Service), so this table is also the
-- idempotency store of the command consumers: redelivery finds the existing row instead of creating a new one.
create table integration_operation (
    id                  uuid primary key,
    kind                text        not null,     -- COMMAND | QUERY
    exception_id        uuid,
    target_system       text        not null,
    action_type         text,
    entity_type         text        not null,
    entity_id           text        not null,
    idempotency_key     text,
    status              text        not null,     -- RECEIVED | ACCEPTED | COMPLETED | FAILED | UNKNOWN
    external_request_id text,
    result              text,
    correlation_id      text,
    revision            bigint      not null,
    version             bigint      not null,
    created_at          timestamptz not null,
    updated_at          timestamptz not null
);
create index ix_operation_external_request on integration_operation (target_system, external_request_id)
    where external_request_id is not null;
create index ix_operation_idempotency_key on integration_operation (target_system, idempotency_key)
    where idempotency_key is not null;
--rollback drop table integration_operation;

--changeset demp:001-integration-attempt
-- One row per TRANSPORT attempt (HTTP call).
create table integration_attempt (
    id           uuid primary key,
    operation_id uuid        not null references integration_operation (id),
    attempt_no   int         not null,
    outcome      text        not null,            -- SUCCESS | NOT_SENT | REJECTED | UNKNOWN
    http_status  int,
    error        text,
    duration_ms  bigint      not null,
    started_at   timestamptz not null
);
create index ix_attempt_operation on integration_attempt (operation_id);
--rollback drop table integration_attempt;

--changeset demp:001-outbox
create table outbox (
    id                uuid primary key,
    aggregate_type    text        not null,
    aggregate_id      text        not null,
    aggregate_version bigint      not null,
    destination       text        not null,
    event_type        text        not null,
    event_version     int         not null,
    payload           jsonb       not null,
    correlation_id    text,
    causation_id      text,
    trace_parent      text,
    created_at        timestamptz not null,
    published_at      timestamptz
);
create index ix_outbox_pending on outbox (created_at, id) where published_at is null;
--rollback drop table outbox;
